perl -e '
use strict;
use warnings;

# Count call sites for specific symbols: exclude declaration lines
my @symbols = qw(
  CompileToStatement NewEngine NewSchema addArg GenUUID Compile
  jsonArrayExpr NewService renderChildren getConstValue Field
  Register ConvertStringToInt32 AllowAnonymous DefaultEngine
  ExtractAll parse Field qualifyColumn sqlOperator
);

open my $blist, "<", "/tmp/backend_go.txt" or die $!;
my @gofiles = <$blist>; chomp @gofiles; close $blist;

for my $name (@symbols) {
  my $total = 0;
  my $prod = 0;
  my $test = 0;
  my $decl = 0;
  my %files;
  my %funcs;
  my $current_func = "?";
  for my $f (@gofiles) {
    open my $fh, "<", $f or next;
    my $n = 0;
    my $is_test = $f =~ /_test\.go$/ ? 1 : 0;
    while (my $line = <$fh>) {
      $n++;
      if ($line =~ /^func\s+(?:\([^)]+\)\s+)?([A-Za-z_][A-Za-z0-9_]*)/) {
        $current_func = $1;
      }
      next unless $line =~ /\b\Q$name\E\s*\(/;
      if ($line =~ /^func\s+/) { $decl++; next; }
      next if $line =~ /^\s*\/\//;
      my $c = () = $line =~ /\b\Q$name\E\s*\(/g;
      $total += $c;
      if ($is_test) { $test += $c; } else { $prod += $c; }
      $files{$f} += $c;
      $funcs{"$f:$current_func"} += $c;
    }
    close $fh;
  }
  print sprintf("%-22s total=%3d  prod=%3d  test=%3d  decl=%d  files=%d  funcs=%d\n",
    $name, $total, $prod, $test, $decl, scalar(keys %files), scalar(keys %funcs));
}
